from decimal import Decimal

from .money import parse_amount, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("Amounts must be a list")

    # Validated amounts have exponent -2, so their coefficients are integer
    # cents. Integer addition is exact regardless of the decimal context.
    total_cents = 0
    for item in amounts:
        amount = parse_amount(item)
        cents = 0
        for digit in amount.as_tuple().digits:
            cents = cents * 10 + digit
        total_cents += cents
        if total_cents > 100000000:
            raise ValueError("Invoice total exceeds 1000000.00")

    total = Decimal((0, tuple(int(digit) for digit in str(total_cents)), -2))
    return {"total": format_amount(total), "count": len(amounts)}

